/* JAH demo program — JAH-NTOOL-000001 */
/* Index Shard Balancer */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("MINIATURE CORE — Index Shard Balancer: inverted index");
var docs=["the archive index maps terms to record ids","chunks hold one hundred records each","the manifest lists every database","search scans the index then ranks hits"];
var idx={};
docs.forEach(function(d,i){d.split(" ").forEach(function(w){(idx[w]=idx[w]||[]).push(i);});});
var q="shard";
console.log("query: "+q);
console.log("hits: "+JSON.stringify(idx[q]||[]));
